  ('hi', 'feature.sensitiveFiles.detail', $json$".env, कुंजियाँ और प्रमाणपत्र जैसी फ़ाइलें कभी संदर्भ में नहीं जातीं।"$json$::jsonb),
  ('hi', 'feature.agentSessions.title', $json$"एजेंट सत्र"$json$::jsonb),
