  ('hi', 'feature.contextCache.title', $json$"संदर्भ कैश"$json$::jsonb),
  ('hi', 'feature.contextCache.detail', $json$"जब तक फ़ाइलें नहीं बदलतीं, किसी अनुरोध के लिए बना संदर्भ कम से कम पाँच मिनट तक दोबारा इस्तेमाल होता है।"$json$::jsonb),
  ('hi', 'feature.answerRecall.title', $json$"पिछले जवाब"$json$::jsonb),
  ('hi', 'feature.answerRecall.detail', $json$"प्रोजेक्ट की किसी दूसरी चैट में पहले से जवाब दिए गए अनुरोध जैसा अनुरोध उसी जवाब से शुरू होता है।"$json$::jsonb),
